/app/packages/shared/test/mail/recipient.content:
import { inputToRecipient, splitBySeparator } from '@proton/shared/lib/mail/recipient';

describe('address input parsing', () => {
    it('splits mixed separators, removes brackets, and skips empty tokens in order', () => {
        expect(splitBySeparator(',plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black,')).toEqual([
            'plus@debye.proton.black',
            'visionary@debye.proton.black',
            'pro@debye.proton.black',
        ]);
        expect(splitBySeparator(' ; <first@example.com> ,, <> ; second@example.com ; ')).toEqual([
            'first@example.com',
            'second@example.com',
        ]);
    });

    it('uses the bare email for both recipient fields', () => {
        expect(inputToRecipient(' plain@example.com ')).toEqual({ Name: 'plain@example.com', Address: 'plain@example.com' });
        expect(inputToRecipient(' <domain@debye.proton.black> ')).toEqual({
            Name: 'domain@debye.proton.black',
            Address: 'domain@debye.proton.black',
        });
    });
});

